"use client";
import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import axios from "axios";
import cookies from "js-cookie";
import Sidebar from "../../../components/sidebar"; // Importation de Sidebar
import Navbar from "../../../components/Navbar";

export default function EtudiantInterface() {
  const { user_id } = useParams();
  const [etudiantData, setEtudiantData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchEtudiantInfo = async () => {
      try {
        const token = cookies.get("token");
        if (!token) {
          throw new Error("Non authentifié");
        }

        const response = await axios.get(
          `http://localhost:5000/api/etudiants/${user_id}`,
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        if (!response.data) {
          throw new Error("Aucune donnée reçue");
        }

        setEtudiantData(response.data);
      } catch (err) {
        console.error("Erreur lors de la récupération des informations :", err);
        setError(
          err.response?.data?.message ||
            err.message ||
            "Erreur lors de la récupération des informations"
        );
      } finally {
        setLoading(false);
      }
    };

    if (user_id) {
      fetchEtudiantInfo();
    } else {
      setError("ID étudiant non fourni");
      setLoading(false);
    }
  }, [user_id]);

  if (loading) {
    return <p className="text-center mt-10 text-gray-500">Chargement...</p>;
  }

  if (error) {
    return <p className="text-red-500 text-center mt-10">{error}</p>;
  }

  if (!etudiantData) {
    return <p className="text-center mt-10 text-gray-500">Aucune information trouvée.</p>;
  }

  const { nom, prenom, email, annee, classe, filiere, groupe } = etudiantData;

  return (
    <div className="flex h-screen w-screen bg-gray-100">
      {/* Sidebar */}
      <Sidebar className="h-screen" />
      <div className="w-full flex flex-col h-screen overflow-hidden">
        {/* Navbar */}
        <Navbar />
        <div className="flex-1 overflow-y-auto p-6">
          <div className="max-w-full mx-auto p-6 bg-white shadow-2xl rounded-lg">
            <h1 className="text-4xl font-bold text-center text-blue-700 mb-8">
              Profil Étudiant
            </h1>

            {/* Informations personnelles */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div className="bg-gradient-to-r from-blue-50 to-blue-100 p-6 rounded-lg shadow-md">
                <h2 className="text-2xl font-semibold text-gray-700 mb-4">Informations générales</h2>
                <div className="space-y-3">
                  <p><span className="font-medium">Nom :</span> {nom}</p>
                  <p><span className="font-medium">Prénom :</span> {prenom}</p>
                  <p><span className="font-medium">Email :</span> {email}</p>
                  <p><span className="font-medium">Année :</span> {annee}</p>
                  <p><span className="font-medium">Classe :</span> {classe}</p>
                  <p><span className="font-medium">Filière :</span> {filiere}</p>
                </div>
              </div>

              {/* Informations du groupe */}
              {groupe && (
                <div className="bg-gradient-to-r from-blue-50 to-blue-100 p-6 rounded-lg shadow-md">
                  <h2 className="text-2xl font-semibold text-blue-700 mb-4">Informations du groupe</h2>
                  <div className="space-y-3">
                    <p><span className="font-medium">Nom du groupe :</span> {groupe.nomGroupe}</p>

                    {/* Tuteur */}
                    {groupe.tuteur ? (
                      <div className="mt-4">
                        <h3 className="text-lg font-semibold text-blue-600">Tuteur</h3>
                        <p><span className="font-medium">Nom :</span> {groupe.tuteur.nom}</p>
                        <p><span className="font-medium">Prénom :</span> {groupe.tuteur.prenom}</p>
                      </div>
                    ) : (
                      <p className="text-gray-500">Aucun tuteur assigné.</p>
                    )}

                    {/* Sujet */}
                    {groupe.sujet ? (
                      <div className="mt-4">
                        <h3 className="text-lg font-semibold text-blue-600">Sujet</h3>
                        <p><span className="font-medium">Titre :</span> {groupe.sujet.titre}</p>
                      </div>
                    ) : (
                      <p className="text-gray-500">Aucun sujet assigné.</p>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Étudiants du groupe */}
            {groupe && groupe.etudiants && groupe.etudiants.length > 0 ? (
              <div className="bg-gradient-to-r from-blue-50 to-blue-100 p-6 rounded-lg shadow-md mb-8">
                <h2 className="text-2xl font-semibold text-blue-700 mb-4">Étudiants du groupe</h2>
                <ul className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {groupe.etudiants.map((etudiantGroupe, index) => (
                    <li key={index} className="bg-white p-4 rounded-lg shadow-sm">
                      <p><span className="font-medium">Nom :</span> {etudiantGroupe.nom} {etudiantGroupe.prenom}</p>
                    </li>
                  ))}
                </ul>
              </div>
            ) : (
              <p className="text-gray-500 text-center">Aucun étudiant dans ce groupe.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}